mapper.sql:
s.is_deleted = 0
AND s.strategy_id != '999' AND s.channel != '全部'
AND s.big_category != '全部' AND COALESCE(s.small_category, '') != '全部'


        AND EXISTS (SELECT 1 FROM v_sr_strategy_read product
            WHERE product.strategy_code = s.strategy_id AND product.tab_type = 'control'
              AND product.is_deleted = 0)

            AND s.small_category = #{query.productName}



        AND s.tab_type = #{query.tabType}


                AND s.strategy_class = #{query.strategyClass}


                AND s.strategy_class IN ('升接', '稳', '重点客群')



        AND EXISTS (SELECT 1 FROM t_sr_strategy_key_audience cg
            WHERE cg.strategy_code = s.strategy_id AND cg.tab_type = 'active'
              AND cg.strategy_class = '重点客群' AND cg.is_deleted = 0
              AND cg.customer_group = #{query.customerGroup})



AND s.city_id = #{query.cityId}
AND s.county_id = #{query.countyId}
AND (s.channel = #{query.channel} OR s.channel IN (SELECT d.key_code FROM t_sr_dim_channel d WHERE d.key_name = #{query.channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{query.tabType} OR FIND_IN_SET(#{query.tabType}, d.tab_type) > 0)))
AND s.big_category = #{query.bigCategory}
AND s.small_category = #{query.smallCategory}
AND s.strategy_name LIKE CONCAT('%', #{query.strategyName}, '%')
AND s.stat_month >= DATE_SUB(CONCAT(#{query.statMonth}, '-01'), INTERVAL 12 MONTH)
AND s.stat_month < DATE_ADD(CONCAT(#{query.statMonth}, '-01'), INTERVAL 1 MONTH)

d.is_deleted = 0 AND d.tab_type = #{query.tabType}
AND d.strategy_id != '999' AND d.channel != '全部'
AND d.big_category != '全部' AND COALESCE(d.small_category, '') != '全部'


        AND d.strategy_class IN ('升接', '稳', '重点客群')


        AND d.strategy_class = #{query.strategyClass}



    AND EXISTS (SELECT 1 FROM t_sr_strategy_key_audience cg
        WHERE cg.strategy_code = d.strategy_id AND cg.tab_type = 'active'
          AND cg.strategy_class = '重点客群' AND cg.is_deleted = 0
          AND cg.customer_group = #{query.customerGroup})

AND d.city_id = #{query.cityId}
AND d.county_id = #{query.countyId}

    AND (d.channel = #{query.channel} OR d.channel IN (SELECT ch.key_code FROM t_sr_dim_channel ch
        WHERE ch.key_name = #{query.channel} AND ch.status = 1 AND ch.is_deleted = 0
          AND (ch.tab_type = #{query.tabType} OR FIND_IN_SET(#{query.tabType}, ch.tab_type) > 0)))

AND d.big_category = #{query.bigCategory}
AND d.small_category = #{query.smallCategory}
AND d.strategy_name LIKE CONCAT('%', #{query.strategyName}, '%')

mapper.select:
SELECT q.biz_name AS bizName, q.manual_qoq AS qoq FROM t_sr_strategy_biz_capacity_qoq_manual q WHERE q.status = 1 AND q.manual_qoq IS NOT NULL AND q.tab_type = #{query.tabType} AND q.strategy_class = '全部' #{query.strategyClass}
AND q.stat_month >= STR_TO_DATE(CONCAT(#{query.statMonth}, '-01'), '%Y-%m-%d') AND q.stat_month < DATE_ADD(STR_TO_DATE(CONCAT(#{query.statMonth}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH) AND q.customer_group = #{query.customerGroup} '全部'
AND q.big_category = #{query.bigCategory} '全部'
AND q.small_category = #{query.smallCategory} '全部'
AND (
q.channel = '全部' OR q.channel = #{query.channel} OR q.channel IN (SELECT d.key_code FROM t_sr_dim_channel d WHERE d.key_name = #{query.channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{query.tabType} OR FIND_IN_SET(#{query.tabType}, d.tab_type) > 0))
q.channel = '全部'
) AND (
q.city_id = '全部' OR q.city_id = #{query.cityId} q.city_id = '全部'
) AND (
q.county_id = '全部' OR q.county_id = #{query.countyId} q.county_id = '全部'
) ORDER BY CASE WHEN q.channel = '全部' THEN 0 ELSE 1 END DESC, CASE WHEN q.city_id = '全部' THEN 0 ELSE 1 END DESC, CASE WHEN q.county_id = '全部' THEN 0 ELSE 1 END DESC, q.update_time DESC

